/** Projection capture and input adapter. Widgets consume one immutable frame, never query flight state. */
public final class NativeSpaceNavigationClient {
    private static NativeFlightSnapshot snapshot;
    private static net.minecraft.client.multiplayer.ClientLevel level;
    private static String receipt="",motionReceipt="";
    private static long drawnTick;
    private static net.minecraft.client.KeyMapping lockKey,nextKey;
    private static int locked=-1;private static Object lockBody,lockLevel,hintedBody;
    private static List<NativeSpaceNavigation.Candidate> candidates=List.of();
    private static void validateLock(){var mc=Minecraft.getInstance();var body=NativeHelmClient.body();if(body!=hintedBody&&body==null)hintedBody=null;if(!NativeSpaceClient.active()||body==null||NativeHelmClient.tier()<2||body!=lockBody||mc.level!=lockLevel||locked>=NativeGroundClient.ephemeris().count())lock(-1);lockBody=body;lockLevel=mc.level;}
    private static void lock(int planet){if(locked==planet)return;locked=planet;var mc=Minecraft.getInstance();if(mc.getConnection()!=null)net.neoforged.neoforge.network.PacketDistributor.sendToServer(new NativeSpacePackets.Target(planet));if(planet>=0&&mc.player!=null&&NativeHelmClient.body()!=null){var ids=cycle();String text=caption(planet,ids.indexOf(planet)+1,ids.size(),mc.getWindow().getGuiScaledWidth()-32);mc.player.displayClientMessage(net.minecraft.network.chat.Component.literal(text),true);}}
    private static List<Integer> cycle(){var frame=NativeSpaceClient.frame();var model=NativeGroundClient.ephemeris();double tick=NativeSpaceClient.time();var at=NativeHelmClient.body().logicalPose().position();return NativeSpaceNavigation.cycle(model,frame.universe(new Point(at.x,at.y,at.z),model,tick),tick,frame.planet());}
    static String caption(int planet,int rank,int count,int width){return NativePlanetIdentity.caption(planet,NativePlanetSystem.identity(planet).label(net.minecraft.client.resources.language.I18n::get),rank,count,width,Minecraft.getInstance().font::width);}
    /** Before vanilla queues an offhand click (Key input events are too late to cancel the key). */
    public static boolean key(long window,int key,int scan,int action){
        var mc=Minecraft.getInstance();if(window!=mc.getWindow().getWindow()||mc.screen!=null||lockKey==null||nextKey==null||(!lockKey.matches(key,scan)&&!nextKey.matches(key,scan))||NativeHelmClient.body()==null)return false;
        validateLock();if(NativeHelmClient.tier()<2){if(action==org.lwjgl.glfw.GLFW.GLFW_PRESS&&hintedBody!=NativeHelmClient.body()){hintedBody=NativeHelmClient.body();mc.player.displayClientMessage(net.minecraft.network.chat.Component.translatable("hud.starfold.instrument_scope_required"),true);}return true;}
        if(action==org.lwjgl.glfw.GLFW.GLFW_PRESS&&visible()&&level==mc.level){if(nextKey.matches(key,scan)){var frame=NativeSpaceClient.frame();var model=NativeGroundClient.ephemeris();double tick=NativeSpaceClient.time();var at=NativeHelmClient.body().logicalPose().position();lock(NativeSpaceNavigation.next(model,frame.universe(new Point(at.x,at.y,at.z),model,tick),tick,locked,frame.planet()));return true;}int chosen=NativeSpaceNavigation.choose(candidates,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight());boolean empty=chosen<0&&locked<0;lock(chosen==locked?-1:chosen);if(empty)mc.player.displayClientMessage(net.minecraft.network.chat.Component.translatable("hud.starfold.space_no_target"),true);}
        return true;
    }
    static int locked(){validateLock();return locked;}
    public static void initialize(net.neoforged.bus.api.IEventBus modBus){
        lockKey=new net.minecraft.client.KeyMapping("key.starfold.lock_planet",com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM,org.lwjgl.glfw.GLFW.GLFW_KEY_F,"key.categories.starfold");
        nextKey=new net.minecraft.client.KeyMapping("key.starfold.next_planet",com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM,org.lwjgl.glfw.GLFW.GLFW_KEY_G,"key.categories.starfold");
        modBus.addListener((net.neoforged.neoforge.client.event.RegisterKeyMappingsEvent event)->{event.register(lockKey);event.register(nextKey);});
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.client.event.ClientTickEvent.Post event)->{validateLock();NativeLandingClient.tick();});
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((RenderLevelStageEvent event)->{if(event.getStage()==RenderLevelStageEvent.Stage.AFTER_LEVEL)capture(new LocalRender(event));});
        net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.client.event.RenderGuiLayerEvent.Pre event)->{if(NativeHelmClient.body()!=null&&(event.getName().equals(net.neoforged.neoforge.client.gui.VanillaGuiLayers.HOTBAR)||event.getName().equals(net.neoforged.neoforge.client.gui.VanillaGuiLayers.CROSSHAIR)))event.setCanceled(true);});
        modBus.addListener((net.neoforged.neoforge.client.event.RegisterGuiLayersEvent event)->event.registerAboveAll(net.minecraft.resources.ResourceLocation.parse("starfold:space_navigation"),(g,t)->render(g)));
    }
    private static boolean visible(){var mc=Minecraft.getInstance();return NativeSpaceClient.active()&&!NativeGroundFlightClient.controlled()&&!mc.options.hideGui&&mc.screen==null;}
    /** Capture the world projection before vanilla replaces it with the GUI orthographic projection. */
    private static void capture(LocalRender context){
        validateLock();snapshot=null;candidates=List.of();receipt="";level=null;var mc=Minecraft.getInstance();var helm=NativeHelmClient.body();int tier=NativeHelmClient.tier();if(helm==null||tier==0||mc.options.hideGui||mc.screen!=null)return;
        NativeWaypointClient.capture(context);boolean chart=NativeLandingClient.active();if(!chart&&!visible())return;
        var pointer=NativeSpaceAttitudeClient.drawnPointer(mc.getTimer().getGameTimeDeltaPartialTick(false));double pointerScale=mc.getWindow().getGuiScaledHeight()/3.0/NativeSpaceAttitudeClient.AIM;
        var thrust=thrust(helm);var flight=NativeHelmInputClient.state(helm.getUniqueId());if(flight==null)return;boolean boost=flight.boosted();
        var launch=NativeWaypointClient.active();int launchPlanet=launch==null?-1:launch.planet();
        if(chart){int planet=NativeGroundClient.planet();var ground=NativeLandingClient.ground();var motion=hullVector(helm,NativeLandingClient.motion());var up=hullVector(helm,new Point(0,1,0));var nose=NativeHelmClient.forward(helm);var bounds=helm.getPlot().getBoundingBox();var lift=NativeHelmInputClient.lift(helm);var landing=new NativeFlightSnapshot.Landing(lift!=null?lift.limit():Double.NaN,motion,Math.atan2(-up.x(),up.y()),Math.asin(Math.clamp(nose.y,-1,1)),bounds.maxX()-bounds.minX()+1,bounds.maxZ()-bounds.minZ()+1,NativeLandingClient.site());snapshot=new NativeFlightSnapshot(tier,NativeFlightSnapshot.Mode.CHART,planet,Math.hypot(NativeLandingClient.horizontal(),NativeLandingClient.vertical()),planet,flight.cruiseCap(),flight.boostCap(),boost,0,null,List.of(),GroundEphemeris.ZERO,null,false,GroundEphemeris.ZERO,planet,thrust,0,0,ground.clearance(),NativeLandingClient.vertical(),NativeLandingClient.horizontal(),launchPlanet,null,landing,NativeWaypointClient.home(),NativeArrivalState.Phase.CRUISE,0,0);level=mc.level;return;}
        var frame=NativeSpaceClient.frame();var model=NativeGroundClient.ephemeris();double tick=NativeSpaceClient.time();
        var eye=NativeSpaceClient.universeEye(mc.player.getEyePosition(mc.getTimer().getGameTimeDeltaPartialTick(false)));var viewEye=NativeSpaceClient.universeEye(context.camera().getPosition());var projection=context.projectionMatrix();
        double fov=2*Math.atan(1/projection.m11()),aspect=projection.m11()/projection.m00();int width=mc.getWindow().getGuiScaledWidth(),height=mc.getWindow().getGuiScaledHeight();var list=new ArrayList<NativeFlightSnapshot.Target>();
        var choices=new ArrayList<NativeSpaceNavigation.Candidate>();var nearest=NativeSpaceView.nearest(model,eye,tick,4);var nose=NativeHelmClient.forward(helm);
        for(int id=0;id<model.count();id++){
            var relative=NativeSpaceView.relative(frame,viewEye,model.at(id,tick).center());
            var camera=new org.joml.Matrix4d(context.positionMatrix()).transformPosition(new org.joml.Vector3d(relative.x(),relative.y(),relative.z()));
            var marker=NativeSpaceNavigation.project(new Point(camera.x,camera.y,camera.z),fov,aspect,Math.min(.2,12.0/width),Math.min(.2,24.0/height));
            var toward=frame.levelVector(model.at(id,tick).center().sub(eye));double angle=Math.toDegrees(Math.acos(Math.clamp((toward.x()*nose.x+toward.y()*nose.y+toward.z()*nose.z)/Math.max(1e-12,toward.length()),-1,1)));
            if(nearest.contains(id)||id==locked){var read=NativeSpaceNavigation.read(model,frame,eye,id,tick);list.add(new NativeFlightSnapshot.Target(id,marker,read.distance(),read.closing(),angle));}choices.add(new NativeSpaceNavigation.Candidate(id,marker,angle));
        }
        var at=helm.logicalPose().position();var pivot=frame.universe(new Point(at.x,at.y,at.z),model,tick);int planet=NativeSpace.nearest(model,pivot,tick);
        var velocity=NativeSpaceNavigation.velocity(model,frame,locked,tick);var local=frame.levelVector(velocity);var cameraVelocity=new org.joml.Matrix4d(context.positionMatrix()).transformDirection(new org.joml.Vector3d(local.x(),local.y(),local.z()));var shown=NativeSpaceNavigation.velocityMarker(new Point(cameraVelocity.x,cameraVelocity.y,cameraVelocity.z));
        var velocityMarker=shown==null?null:NativeSpaceNavigation.project(shown.camera(),fov,aspect,Math.min(.2,12.0/width),Math.min(.2,24.0/height));
        int relativeTo=locked>=0?locked:frame.planet();motionReceipt="";if(DevProbe.active()){var toward=model.at(relativeTo,tick).center().sub(eye);double separation=Math.toDegrees(Math.acos(Math.clamp(velocity.dot(toward)/Math.max(1e-12,velocity.length()*toward.length()),-1,1)));motionReceipt=" | viewport "+width+"x"+height+" | reference "+frame.planet()+" drift "+frame.drift()+" | relativeVelocity "+velocity+" cameraVelocity "+cameraVelocity+" separation "+separation;}
        int bearingPlanet=NativeSpaceClient.arriving()?planet:frame.planet();var direction=frame.levelVector(model.at(bearingPlanet,tick).center().sub(pivot));var hullDirection=helm.logicalPose().orientation().conjugate(new org.joml.Quaterniond()).transform(new org.joml.Vector3d(direction.x(),direction.y(),direction.z()));var facing=NativeHelmInputClient.facing(helm);var forward=new org.joml.Vector3d(facing.getStepX(),0,facing.getStepZ());var right=new org.joml.Vector3d(forward).cross(0,1,0);var bearing=new Point(hullDirection.dot(right),hullDirection.y,hullDirection.dot(forward));
        var cycle=NativeSpaceNavigation.cycle(model,pivot,tick,frame.planet());list.replaceAll(t->new NativeFlightSnapshot.Target(t.planet(),t.marker(),t.distance(),t.closing(),t.angle(),cycle.indexOf(t.planet())+1,cycle.size(),tier>=2&&t.planet()==locked?NativeSpaceNavigation.blocker(model,pivot,locked,tick):-1));
        list.sort(Comparator.comparingInt(t->nearest.contains(t.planet())?nearest.indexOf(t.planet()):nearest.size()));var target=list.stream().filter(t->t.planet()==locked).findFirst().orElse(null);
        var arrival=NativeSpaceClient.phase()!=NativeArrivalState.Phase.CRUISE?arrival(context,helm,frame,model,pivot,planet,tick):null;
        snapshot=new NativeFlightSnapshot(tier,NativeSpaceClient.arriving()?NativeFlightSnapshot.Mode.ARRIVAL:NativeFlightSnapshot.Mode.FREE,planet,velocity.length()*20,relativeTo,flight.cruiseCap(),flight.boostCap(),boost,target==null?0:target.closing(),target,list,velocity,velocityMarker,shown!=null&&shown.retrograde(),bearing,bearingPlanet,thrust,pointer.x()*pointerScale,pointer.y()*pointerScale,Double.NaN,0,0,launchPlanet,arrival,null,null,NativeSpaceClient.phase(),NativeSpaceClient.blend(),NativeSpaceClient.notice());
        candidates=List.copyOf(choices);level=mc.level;
    }
    private static Point hullVector(dev.ryanhcode.sable.sublevel.ClientSubLevel hull,Point vector){var v=hull.logicalPose().orientation().conjugate(new org.joml.Quaterniond()).transform(new org.joml.Vector3d(vector.x(),vector.y(),vector.z()));var facing=NativeHelmInputClient.facing(hull);var forward=new org.joml.Vector3d(facing.getStepX(),0,facing.getStepZ());return new Point(v.dot(new org.joml.Vector3d(forward).cross(0,1,0)),v.y,v.dot(forward));}
    private static NativeFlightSnapshot.Arrival arrival(LocalRender context,dev.ryanhcode.sable.sublevel.ClientSubLevel hull,NativeSpace.Frame frame,GroundEphemeris.Model model,Point pivot,int planet,double tick){
        double height=NativeSpace.height(model,planet,pivot,tick);var toward=model.at(planet,tick).center().sub(pivot);var radial=toward.scale(1/Math.max(1e-12,toward.length()));var relative=frame.universeVelocity(GroundEphemeris.ZERO,model,tick).sub(model.at(planet,tick).velocity());var d=hullVector(hull,frame.levelVector(radial));
        var point=pivot.add(radial.scale(Math.max(0,height-NativeSpace.IN)));var viewEye=NativeSpaceClient.universeEye(context.camera().getPosition());var local=NativeSpaceView.relative(frame,viewEye,point);var camera=new org.joml.Matrix4d(context.positionMatrix()).transformPosition(new org.joml.Vector3d(local.x(),local.y(),local.z()));var p=context.projectionMatrix();var marker=NativeSpaceNavigation.project(new Point(camera.x,camera.y,camera.z),2*Math.atan(1/p.m11()),p.m11()/p.m00(),.05,.1);
        return new NativeFlightSnapshot.Arrival(Math.max(0,height-NativeSpace.IN),relative.dot(radial)*20,NativeSpaceServer.arrivalLimit(height),NativeSpaceServer.nearLimit(height),marker,1-Math.acos(Math.clamp(-d.y(),-1,1))/Math.PI,new NativeFlightSnapshot.Thrust(Math.abs(d.z())<1e-3,Math.abs(d.z())<1e-3,Math.abs(d.x())<1e-3,Math.abs(d.x())<1e-3,false,Math.abs(d.y())<1e-3));
    }
    private static NativeFlightSnapshot.Thrust thrust(dev.ryanhcode.sable.sublevel.ClientSubLevel hull){boolean f=false,b=false,l=false,r=false,u=false,d=false;var facing=NativeHelmInputClient.facing(hull);var nose=new org.joml.Vector3d(facing.getStepX(),0,facing.getStepZ());var right=new org.joml.Vector3d(nose).cross(0,1,0);for(var actor:hull.getPlot().getBlockEntityActors())if(actor instanceof NativeThruster.Thruster jet&&!jet.isRemoved()&&NativeHelmInputClient.power(jet.getLevel(),jet.getBlockPos(),jet.getBlockState())>0){var push=jet.getBlockState().getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING).getOpposite();var v=new org.joml.Vector3d(push.getStepX(),push.getStepY(),push.getStepZ());f|=v.dot(nose)>.5;b|=v.dot(nose)<-.5;l|=v.dot(right)<-.5;r|=v.dot(right)>.5;u|=v.y>.5;d|=v.y<-.5;}var lift=NativeHelmInputClient.lift(hull);return new NativeFlightSnapshot.Thrust(f,b,l,r,u,d,lift==null?null:new NativeFlightSnapshot.Lift(lift.up(),lift.insufficient()));}
    private static void render(GuiGraphics g){receipt="";var mc=Minecraft.getInstance();if(mc.options.hideGui||mc.screen!=null||NativeHelmClient.body()==null)return;NativeFlightWidgets.view(g,NativeHelmClient.viewLabel(),NativeHelmClient.viewFlash());if(snapshot==null||level!=mc.level)return;RenderSystem.disableDepthTest();try{NativeFlightWidgets.render(g,snapshot);receipt=" | instruments tier "+snapshot.tier()+" mode "+snapshot.mode()+" speed "+snapshot.speed()+" boost "+snapshot.boosted()+" closing "+snapshot.closing()+" | lock "+locked+" | velocity "+snapshot.velocityMarker()+" retro "+snapshot.retrograde()+" | layout "+NativeHudLayout.layout(g.guiWidth(),g.guiHeight());for(var t:snapshot.planets())receipt+=" | planet "+t.planet()+" marker "+t.marker()+" angle "+t.angle()+" eta "+t.eta();if(DevProbe.active())receipt+=" | identities "+NativePlanetSystem.identities()+" | caption "+(snapshot.target()==null?"—":caption(snapshot.target().planet(),snapshot.target().rank(),snapshot.target().count(),NativeHudLayout.layout(g.guiWidth(),g.guiHeight()).mode().width()));receipt+=" | blocker "+(snapshot.target()==null?-1:snapshot.target().blocker());receipt+=" | clearance "+snapshot.clearance()+" vertical "+snapshot.vertical()+" horizontal "+snapshot.horizontal()+" arrival "+snapshot.arrival()+" landing "+snapshot.landing()+" home "+snapshot.home()+" launchPlanet "+snapshot.launchPlanet();receipt+=motionReceipt;drawnTick=mc.level.getGameTime();}finally{RenderSystem.enableDepthTest();}}
    static void arrow(GuiGraphics g,int x,int y,double angle,int color){double dx=Math.cos(angle),dy=Math.sin(angle);for(int i=0;i<=6;i++)for(int sign:new int[]{-1,1}){int px=(int)Math.round(x-dx*i-dy*i*.6*sign),py=(int)Math.round(y-dy*i+dx*i*.6*sign);g.fill(px,py,px+2,py+2,color|0xff000000);}}
    static String probeReading(){var mc=Minecraft.getInstance();return snapshot!=null&&level==mc.level&&mc.level.getGameTime()-drawnTick<=2?receipt:"";}
    private NativeSpaceNavigationClient(){}
}
